    public function overview():array {return ['keys'=>$this->db->fetchAll('SELECT credential_id,site_id,label,scopes_json,expires_at,revoked_at,last_used_at,created_at FROM integration_credentials WHERE company_id=:company ORDER BY credential_id DESC LIMIT 200',['company'=>$this->company()]),'webhooks'=>$this->db->fetchAll('SELECT webhook_id,site_id,label,endpoint_url,enabled,created_at FROM integration_webhooks WHERE company_id=:company ORDER BY webhook_id DESC LIMIT 100',['company'=>$this->company()]),'deliveries'=>$this->db->fetchAll('SELECT delivery_id,webhook_id,event_id,state,attempts,last_http_status,last_result,attempted_at FROM webhook_deliveries WHERE company_id=:company ORDER BY delivery_id DESC LIMIT 200',['company'=>$this->company()])];}
    public function createKey(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['site_id','label','scopes','valid_days']);$site=$this->access->requireSite($input['site_id']??null);$scopes=$input['scopes']??null;if(!is_array($scopes)||!array_is_list($scopes)||!$scopes||count($scopes)>3||array_diff($scopes,['alarms.write','access.write','exports.read']))throw HttpException::unprocessable('Choose alarms.write, access.write or exports.read.');$secret='snt_'.bin2hex(random_bytes(32));$this->db->execute('INSERT INTO integration_credentials(company_id,site_id,client_id,label,key_hash,scopes_json,created_by_user_id,created_at,expires_at) VALUES(:company,:site,:client,:label,:hash,:scopes,:actor,:now,:expiry)',['company'=>$this->company(),'site'=>$site['site_id'],'client'=>$site['client_id'],'label'=>$this->text($input['label']??null,100),'hash'=>hash('sha256',$secret),'scopes'=>json_encode(array_values(array_unique($scopes)),JSON_THROW_ON_ERROR),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'expiry'=>gmdate('Y-m-d H:i:s',time()+$this->number($input['valid_days']??null,1,90)*86400)]);return $this->created('integration_credential')+['api_key'=>$secret,'note'=>'Copy this key now. It is not stored in recoverable form.'];});}
