    public function event(string $site,string $type,array $payload):array {return $this->atomic(function()use($site,$type,$payload){$record=$this->site($site);$uuid=uuid4();$now=gmdate('Y-m-d H:i:s');$body=json_encode(['event_id'=>$uuid,'event_type'=>$type,'site_id'=>$site,'occurred_at'=>$now,'data'=>$payload],JSON_THROW_ON_ERROR);if(strlen($body)>10000)throw HttpException::unprocessable('Event payload exceeds the delivery limit.');$this->db->execute('INSERT INTO integration_events(company_id,site_id,client_id,event_uuid,event_type,payload_json,created_at) VALUES(:company,:site,:client,:uuid,:type,:payload,:now)',['company'=>$this->company(),'site'=>$site,'client'=>$record['client_id'],'uuid'=>$uuid,'type'=>$type,'payload'=>$body,'now'=>$now]);$id=(string)$this->db->connection()->lastInsertId();foreach($this->db->fetchAll('SELECT webhook_id FROM integration_webhooks WHERE company_id=:company AND site_id=:site AND client_id=:client AND enabled=1',['company'=>$this->company(),'site'=>$site,'client'=>$record['client_id']])as$w)$this->db->execute('INSERT INTO webhook_deliveries(company_id,webhook_id,event_id,next_attempt_at) VALUES(:company,:webhook,:event,:now)',['company'=>$this->company(),'webhook'=>$w['webhook_id'],'event'=>$id,'now'=>$now]);return ['event_id'=>$uuid];});}
    public function incoming(string $secret,string $scope,array $input):array {
        if(strlen($secret)>100||!str_starts_with($secret,'snt_'))throw HttpException::unauthorized('Invalid integration credential.');$key=$this->db->fetch('SELECT * FROM integration_credentials WHERE key_hash=:hash',['hash'=>hash('sha256',$secret)]);if(!$key||$key['revoked_at']!==null||$key['expires_at']<=gmdate('Y-m-d H:i:s')||!in_array($scope,json_decode($key['scopes_json'],true),true))throw HttpException::unauthorized('Invalid, expired or insufficient integration credential.');
