    private function receive(array $key,string $scope,array $input):array {return $this->atomic(function()use($key,$scope,$input){$current=$this->row('integration_credentials','credential_id',$key['credential_id']);$p=new PermissionRepository($this->db,$this->context);if($current['revoked_at']!==null||$current['expires_at']<=gmdate('Y-m-d H:i:s')||!$p->userHasPermission($this->actor(),'integrations.manage')||$p->userHasPermission($this->actor(),'site_scope.restricted'))throw HttpException::unauthorized('Integration access changed.');$site=$this->access->requireSite($key['site_id']);if((string)$site['client_id']!==(string)$current['client_id'])throw HttpException::unauthorized('The integration site/client assignment changed.');if($scope!=='exports.read'&&in_array($site['status']??'ACTIVE',['CLOSED','INACTIVE','SUSPENDED','CONTRACT_EXPIRED'],true))throw HttpException::conflict('Integration writes require an available site.');$this->db->execute('UPDATE integration_credentials SET last_used_at=:now WHERE company_id=:company AND credential_id=:id',['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$key['credential_id']]);if($scope==='exports.read'){$this->fields($input,['date_from','date_to']);$from=$this->day($input['date_from']??null);$to=$this->day($input['date_to']??null);if($to<$from||strtotime($to.' UTC')-strtotime($from.' UTC')>31*86400)throw HttpException::unprocessable('Choose at most 32 days.');$rows=$this->db->fetchAll('SELECT attendance_id,employee_id,site_id,shift_date,clock_in_at,clock_out_at FROM attendance WHERE company_id=:company AND site_id=:site AND deleted_at IS NULL AND shift_date>=:start AND shift_date<=:end ORDER BY attendance_id LIMIT 5001',['company'=>$this->company(),'site'=>$key['site_id'],'start'=>$from,'end'=>$to]);if(count($rows)>5000)throw HttpException::unprocessable('Export is too large.');foreach($rows as&$row){$approval=$this->db->fetch('SELECT record_hash FROM attendance_approvals WHERE company_id=:company AND attendance_id=:id',['company'=>$this->company(),'id'=>$row['attendance_id']]);$row['approval_state']=$approval?(hash_equals($approval['record_hash'],FieldOperationsService::attendanceHash($row))?'CURRENT':'STALE'):'UNAPPROVED';$seconds=!empty($row['clock_in_at'])&&!empty($row['clock_out_at'])?strtotime($row['clock_out_at'].' UTC')-strtotime($row['clock_in_at'].' UTC'):0;$row['approved_worked_seconds']=$row['approval_state']==='CURRENT'&&$seconds>0&&$seconds<=172800?$seconds:null;}unset($row);$this->audit->record('integration_export','read',(string)$key['credential_id']);return ['site_id'=>$key['site_id'],'attendance'=>$rows,'note'=>'Recorded attendance only; verify approvals and apply payroll calculations in the receiving system.'];}
        $this->fields($input,$scope==='alarms.write'?['operation_uuid','title','description','severity']:['operation_uuid','visitor_name','purpose','direction']);$uuid=$input['operation_uuid']??null;if(!is_string($uuid)||!preg_match('/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/Di',$uuid))throw HttpException::unprocessable('Use an operation UUID.');$uuid=strtolower($uuid);$canonical=$input;ksort($canonical);$hash=hash('sha256',$scope.json_encode($canonical,JSON_THROW_ON_ERROR));$old=$this->db->fetch('SELECT request_hash,response_json FROM integration_receipts WHERE company_id=:company AND credential_id=:key AND operation_uuid=:uuid',['company'=>$this->company(),'key'=>$key['credential_id'],'uuid'=>$uuid]);if($old){if(!hash_equals($old['request_hash'],$hash))throw HttpException::conflict('Operation UUID already used for different data.');return json_decode($old['response_json'],true,512,JSON_THROW_ON_ERROR);}$now=gmdate('Y-m-d H:i:s');
        if($scope==='alarms.write'){$severity=$input['severity']??null;if(!in_array($severity,['LOW','MEDIUM','HIGH','CRITICAL'],true))throw HttpException::unprocessable('Invalid alarm severity.');$this->db->execute('INSERT INTO incidents(incident_uuid,company_id,site_id,reporter_user_id,incident_number,incident_type,incident_category,severity,occurred_at,description,created_by_user_id) VALUES(:uuid,:company,:site,:actor,:number,:type,:category,:severity,:now,:description,:creator)',['uuid'=>uuid4(),'company'=>$this->company(),'site'=>$key['site_id'],'actor'=>$this->actor(),'number'=>'EXT-'.substr(uuid4(),0,20),'type'=>'EXTERNAL_ALARM','category'=>'INTEGRATION','severity'=>$severity,'now'=>$now,'description'=>$this->text($input['title']??null,150).' — '.$this->text($input['description']??null,4000),'creator'=>$this->actor()]);$id=(string)$this->db->connection()->lastInsertId();$type='alarm.received';}else{if(!in_array($input['direction']??null,['ENTRY','EXIT'],true))throw HttpException::unprocessable('Choose ENTRY or EXIT.');$this->db->execute('INSERT INTO gate_register(company_id,operation_uuid,request_hash,site_id,visitor_name,purpose,direction,authorization,occurred_at,received_at,recorded_by_user_id) VALUES(:company,:uuid,:hash,:site,:name,:purpose,:direction,:auth,:now,:received,:actor)',['company'=>$this->company(),'uuid'=>uuid4(),'hash'=>$hash,'site'=>$key['site_id'],'name'=>$this->text($input['visitor_name']??null,150),'purpose'=>$this->text($input['purpose']??null,500),'direction'=>$input['direction'],'auth'=>'PENDING','now'=>$now,'received'=>$now,'actor'=>$this->actor()]);$id=(string)$this->db->connection()->lastInsertId();$type='access.received';}$result=['received'=>true,'record_id'=>$id,'site_id'=>(string)$key['site_id']];$this->db->execute('INSERT INTO integration_receipts(company_id,credential_id,operation_uuid,request_hash,response_json,received_at) VALUES(:company,:key,:uuid,:hash,:response,:now)',['company'=>$this->company(),'key'=>$key['credential