    });}
    public function retry(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['reason']);$r=$this->row('webhook_deliveries','delivery_id',$id);if(!in_array($r['state'],['UNCERTAIN','FAILED'],true))throw HttpException::conflict('Only failed or uncertain deliveries need a reviewed retry.');$this->db->execute("UPDATE webhook_deliveries SET state='PENDING',attempts=0,next_attempt_at=:now WHERE company_id=:company AND delivery_id=:id",['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('webhook_delivery','reviewed_retry',$id,[],[],['reason'=>$this->text($input['reason']??null,1000)]);return ['retry_queued'=>true];});}
    public function deliver():array {
